import { scopeId } from './scopeUtils';
// Persistance
const persist = {
    regular: (value) => {
        return value;
    },
    dummy: () => {
        return '__threlte-studio-persisted-value__';
    }
};
const persistedDummyValue = '__threlte-studio-persisted-value__';
const isObject = (d) => {
    return typeof d === 'object' && !Array.isArray(d) && d !== null;
};
const getPersistedPaths = function (obj, prefix) {
    const keys = Object.keys(obj);
    // eslint-disable-next-line no-param-reassign
    prefix = prefix ? `${prefix}.` : '';
    return keys.reduce((result, key) => {
        if (isObject(obj[key])) {
            // eslint-disable-next-line no-param-reassign
            result = [...result, ...getPersistedPaths(obj[key], prefix + key)];
        }
        else if (obj[key] === persistedDummyValue) {
            result.push(prefix + key);
        }
        return result;
    }, []);
};
export const createState = (namespace, transient) => {
    // eslint-disable-next-line @typescript-eslint/no-empty-function
    const state = $state({});
    // the key is the scope and the value is the path to the persisted state
    const persistedStatePaths = {};
    const addExtensionState = (scope, createState) => {
        const extensionState = createState({ persist: persist.regular });
        if (!transient) {
            const persistedState = createState({ persist: persist.dummy });
            const persistedPaths = getPersistedPaths(persistedState);
            persistedStatePaths[scope] = persistedPaths;
            for (const path of persistedPaths) {
                const scopedKey = scopeId(namespace, scope, path);
                const stringValue = localStorage[scopedKey];
                if (stringValue && stringValue !== 'undefined') {
                    const parsedValue = JSON.parse(stringValue);
                    const pathParts = path.split('.');
                    const lastPart = pathParts.pop();
                    if (!lastPart) {
                        throw new Error(`Path "${path}" is not valid`);
                    }
                    let value = extensionState;
                    for (const pathPart of pathParts) {
                        if (!isObject(value)) {
                            throw new Error(`Path "${path}" is not valid`);
                        }
                        value = value[pathPart];
                    }
                    if (!isObject(value)) {
                        throw new Error(`Path "${path}" is not valid`);
                    }
                    value[lastPart] = parsedValue;
                }
            }
        }
        state[scope] = extensionState;
        return state[scope];
    };
    const getScopedState = (scope) => {
        return {
            get state() {
                return (state[scope] ?? {});
            }
        };
    };
    const removeScopedState = (scope) => {
        // eslint-disable-next-line @typescript-eslint/no-dynamic-delete
        delete state[scope];
        // eslint-disable-next-line @typescript-eslint/no-dynamic-delete
        delete persistedStatePaths[scope];
    };
    const persistState = (scope) => {
        if (transient)
            return;
        for (const [currentScope, paths] of Object.entries(persistedStatePaths)) {
            if (scope && currentScope !== scope)
                continue;
            const state = getScopedState(currentScope).state;
            for (const path of paths) {
                const scopedKey = scopeId(namespace, currentScope, path);
                const pathParts = path.split('.');
                let value = state;
                for (const pathPart of pathParts) {
                    if (!isObject(value)) {
                        throw new Error(`Path "${path}" is not valid`);
                    }
                    value = value[pathPart];
                }
                localStorage[scopedKey] = JSON.stringify(value);
            }
        }
    };
    return {
        addExtensionState,
        getScopedState,
        removeScopedState,
        persistState,
        state
    };
};
